for (const [characterKey, variants] of Object.entries(ADDITIONAL_ROLE_VARIANTS)) {
  const profile = CHARACTER_BUILD_GUIDES[characterKey];
  if (profile) profile.alternateBuilds = [...(profile.alternateBuilds || []), ...variants];
}

